<script setup lang="ts">const shop=useShop()</script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-12"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Your purchases</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">Order history<span class="text-brand">.</span></h1><p class="mb-8 mt-3 text-sm text-gray-500">Orders created by the demo checkout on this browser.</p><div v-if="shop.orders.length" class="space-y-4"><article v-for="order in shop.orders" :key="order.id" class="rounded-2xl border border-gray-100 p-5 sm:p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs text-gray-500">{{ new Date(order.createdAt).toLocaleString() }}</p><h2 class="mt-1 font-semibold">{{ order.id }}</h2><p class="mt-1 text-xs text-gray-500">{{ order.items.length }} line item(s) · {{ order.status }}</p></div><p class="text-lg font-bold">${{ order.total.toFixed(2) }}</p></div><div class="mt-4 border-t border-gray-100 pt-4"><p v-for="item in order.items" :key="item.key" class="py-1 text-sm text-gray-600">{{ item.productName }} · {{ item.color }} / {{ item.size }} × {{ item.quantity }}</p></div></article></div><EmptyState v-else title="Your order story starts here" description="Once you place a demo order, its details will show up here." to="/shop" action-label="Start shopping"/></div></template>
